import json
S={
"ke":{"country":"Kenya","src":{"label":"Embassy of Kenya in Spain — Ministry of Livestock Development conditions for importing dogs and cats","url":"https://kenyaembassyspain.es/wp-content/uploads/2024/11/CONDITIONS-FOR-CANINE-IMPORT.pdf"},
"head":"Kenya wants an import permit, a rabies-tested animal and cargo shipment, not cabin travel.",
"lines":["The Kenyan ministry conditions (published by the embassy in Spain) say a dog or cat needs an international veterinary certificate dated no more than 48 hours before embarkation, showing no sign of rabies or other contagious disease and no internal or external parasites.","Unless the animal spent its first six months in a rabies-free country, it needs a permanent mark such as a microchip, a rabies vaccine given 6 to 12 months before shipment (primary dose from 3 months of age) or within a year (booster), and a rabies antibody test of at least 0.5 IU/ml taken 3 to 24 months before shipment. Animals that do not meet this may be quarantined for up to six months at the owner's cost.","The import permit is valid for a maximum of 30 days and for one consignment, and must travel with the animal. The airline captain must certify the animal stayed on the aircraft and apart from other dogs and cats. The ministry text states that animals travel as manifest cargo in the freight hold, not as baggage or in the cabin."]},
"gr":{"country":"Greece","src":{"label":"Greek Ministry of Foreign Affairs (Embassy in the USA) — pet animals: rules for entering Greece","url":"https://www.mfa.gr/usa/en/services/citizen-services/pets-animals/"},
"head":"Pets from outside the EU must enter through an authorised border inspection post, with a microchip and rabies vaccine.",
"lines":["The Greek foreign ministry page says dogs, cats and ferrets coming from a third country may enter only through an authorised border inspection post. It lists Athens International Airport, Thessaloniki airport and port and Piraeus port, plus a set of island ports and airports such as Rhodes, Kos, Chios, Heraklion, Chania and Corfu.","Over three months of age, the animal needs an ISO 11784/11785 microchip (or a readable tattoo), a rabies vaccine, and an official veterinarian's certificate. A rabies antibody test of at least 0.5 IU/ml, taken 30 days or more after vaccination, is required when the animal comes from a country outside the listed low-risk group.","The page also says pets travelling by public transport must be in a safe cage labelled with the owner's name, address and phone number. The text refers to older EU decisions, so confirm current wording with the Greek veterinary authority."]},
"sa":{"country":"Saudi Arabia","src":{"label":"USDA APHIS — pet travel from the United States to Saudi Arabia (relaying Saudi Ministry of Environment, Water and Agriculture guidance)","url":"https://www.aphis.usda.gov/pet-travel/us-to-another-country-export/pet-travel-us-saudi-arabia"},
"head":"Every dog or cat needs a Saudi import permit arranged by a local sponsor; dogs are mostly refused.",
"lines":["The US agriculture department page, which passes on guidance from the Saudi agriculture ministry, says every dog and cat needs an import permit from the Saudi ministry, applied for by a Saudi sponsor using your pet's details and flight information.","With the permit, the pet must carry an endorsed veterinary health certificate and a certificate of origin obtained from the Saudi ministry. The page says the certificate of origin does not need Saudi embassy attestation.","The same page says dogs are generally not allowed into Saudi Arabia except for hunting, guarding and guides for disabled people. This is a US-side relay of Saudi rules, so confirm with the ministry before booking."]}}
for k,v in S.items(): json.dump(v,open('dup_work/petspecs/%s.json'%k,'w',encoding='utf8'),ensure_ascii=False,separators=(',',':'))
